<?php
declare(strict_types=1);namespace App\Services\Finance;
use App\Models\{Classroom,Student};use App\Models\Finance\{StudentInvoice,StudentInvoiceItem};use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
class SppGenerationService {private function students(?int $classroomId){$q=Student::query()->where('status','active')->with('activeClassroomMembership.classroom');if($classroomId)$q->whereHas('activeClassroomMembership',fn($x)=>$x->where('classroom_id',$classroomId));return $q->orderBy('full_name')->get();}public function preview(array $data):array{return $this->students(isset($data['classroom_id'])?(int)$data['classroom_id']:null)->map(function($s)use($data){$exists=StudentInvoice::where('student_id',$s->id)->where('academic_year_id',$data['academic_year_id'])->whereDate('billing_month',$data['billing_month'].'-01')->exists();return ['student'=>$s,'classroom'=>$s->current_classroom_name,'amount'=>$data['amount'],'exists'=>$exists,'skip'=>$exists];})->all();}public function generate(array $data,?int $actor):array{return DB::transaction(function()use($data,$actor){$created=0;$skipped=0;foreach($this->preview($data) as $row){if($row['skip']){$skipped++;continue;}$invoice=StudentInvoice::create(['student_id'=>$row['student']->id,'academic_year_id'=>$data['academic_year_id'],'semester_id'=>$data['semester_id'],'invoice_number'=>'SPP-'.str_replace('-','',$data['billing_month']).'-'.Str::upper(Str::random(8)),'billing_month'=>$data['billing_month'].'-01','issue_date'=>now()->toDateString(),'due_date'=>$data['due_date'],'subtotal'=>$data['amount'],'total'=>$data['amount'],'outstanding_amount'=>$data['amount'],'status'=>now()->toDateString()>$data['due_date']?'overdue':'open','created_by'=>$actor]);StudentInvoiceItem::create(['invoice_id'=>$invoice->id,'fee_type_id'=>$data['fee_type_id'],'description'=>'SPP '.$data['billing_month'],'qty'=>1,'unit_amount'=>$data['amount'],'amount'=>$data['amount']]);$created++;}return compact('created','skipped');},3);}}
